public class Report {
    public void print() {
        formatHeader();      // fine, called from inside the class
    }

    private void formatHeader() {
        System.out.println("=== REPORT ===");
    }
}

// elsewhere:
new Report().print();          // fine
new Report().formatHeader();   // error: formatHeader() has private access

public class Student {
    private String name;      // private. Nobody outside can touch it directly

    public String getName() { // accessor
        return name;
    }

    public void setName(String name) {   // mutator
        this.name = name;
    }
}

public class Student {
    private double grade;

    public void setGrade(double grade) {
        if (grade < 0 || grade > 100) {
            System.out.println("Invalid grade: " + grade + ". Ignored.");
            return;
        }
        this.grade = grade;
    }

    public double getGrade() {
        return grade;
    }
}
